const menu=document.querySelector('.menu'),nav=document.querySelector('nav');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');nav.classList.toggle('open',open)});nav.addEventListener('click',e=>{if(e.target.closest('a')){menu.setAttribute('aria-expanded','false');nav.classList.remove('open')}});document.addEventListener('keydown',e=>{if(e.key==='Escape'){nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}});const video=document.querySelector('video'),motion=document.querySelector('.motion'),reduced=matchMedia('(prefers-reduced-motion: reduce)');let paused=false;function sync(){if(reduced.matches){video.pause();video.removeAttribute('src');video.load();motion.hidden=true;return}motion.hidden=false;if(!video.getAttribute('src'))video.src='assets/hero.mp4';if(paused||document.hidden)video.pause();else video.play().catch(()=>{motion.textContent='Play film â–¶';motion.setAttribute('aria-label','Play background video')})}video.addEventListener('playing',()=>video.classList.add('ready'));video.addEventListener('error',()=>{video.classList.remove('ready');motion.hidden=true});motion.addEventListener('click',()=>{paused=!paused;motion.textContent=paused?'Play film â–¶':'Pause film â…¡';motion.setAttribute('aria-label',paused?'Play background video':'Pause background video');sync()});document.addEventListener('visibilitychange',sync);reduced.addEventListener('change',sync);sync();
document.querySelector('#year').textContent=new Date().getFullYear();

document.querySelector('#project-form').addEventListener('submit',e=>{e.preventDefault();const status=document.querySelector('#form-status');status.textContent='Your form is complete. This preview does not send inquiries. Please call (215) 699-0600 to discuss your project.';status.focus()});
